/* ===================== RÉGLAGES MACHINES (Technogym Selection/Pure, Hammer Strength) ===================== */
const TIPS=[
 [/latérales machine|plate.?loaded/i,['Machine plate loaded (disques) : règle le siège pour que l\'axe de rotation soit aligné avec l\'articulation de l\'épaule, coudes sous les coussinets.','Dos plaqué, ne te penche pas : le mouvement vient de l\'épaule. Monte jusqu\'à l\'horizontale, pas plus haut.','Pars léger sur les disques : c\'est un travail d\'isolation, 12–15 reps contrôlées, descente lente. Tu peux garder 1–2 reps en réserve.']],
 [/frontales? barre/i,['Barre droite ou EZ, prise un peu plus large que les épaules, barre contre le haut des cuisses.','Monte bras presque tendus jusqu\'à hauteur des yeux, sans balancer le buste, descends en 2–3 s.','Pars léger (barre à vide ou 10–20 kg) : l\'avant d\'épaule travaille déjà beaucoup sur tous tes développés.']],
 [/seal row|banc de rowing/i,['Banc : règle la hauteur pour que la barre pende bras tendus sans toucher le sol (ajoute des disques de réhausse si besoin) et touche le banc en haut du mouvement.','Poitrine en haut du coussin, tête dans l\'axe de la barre, jambes allongées ou bloquées selon le banc.','Prise un peu plus large que les épaules, coudes à ~45° du corps, tire vers le haut des côtes.','Pas d\'élan possible : prévois environ 15–20 % de moins de charge que ton rowing barre classique.']],
 [/high row|rowing haut/i,['Hammer Iso-Lateral High Row (à disques) : règle le siège pour attraper les poignées hautes bras presque tendus, sans que les épaules montent.','Coussin pectoral : contre le haut du sternum, sans écraser le cou ni gêner l\'extension des bras. Pieds au sol ou sur le repose-pieds.','Tire vers le bas des côtes (pas vers le menton), coudes le long du corps.','Charge les disques de façon identique des deux côtés ; tu peux aussi travailler un bras à la fois pour corriger un déséquilibre.']],
 [/presse à cuisses|leg press|hack/i,['Siège / dossier : règle-le pour avoir les genoux à ~90° en bas, sans que le bas du dos décolle (si le bassin se roule, remonte le dossier).','Pieds : milieu de la plateforme, largeur d\'épaules, pointes légèrement ouvertes. Plus haut = plus fessiers/ischios, plus bas = plus quadriceps.','Ne verrouille jamais les genoux en haut. Règle les butées de sécurité avant de charger.','Hammer à disques : charge les deux côtés pareil.']],
 [/leg curl|nordic/i,['Dossier : l\'axe de rotation de la machine doit être aligné avec ton genou (ligne qui passe par l\'articulation).','Rouleau de chevilles : juste au-dessus des talons (au-dessus du tendon d\'Achille), pas sur les mollets.','Cale-cuisses : serré pour bloquer les cuisses. Hanches collées au siège, ne les décolle pas.','Technogym : règle aussi la position de départ pour partir jambes presque tendues, sans douleur derrière le genou.']],
 [/leg extension|sissy/i,['Dossier : le creux du genou touche le bord du siège ; l\'axe de rotation est aligné avec le genou.','Rouleau : sur le bas du tibia, juste au-dessus des chevilles.','Départ à ~90° de flexion (règle la butée de départ). Ne verrouille pas le genou en haut, marque une courte pause.','Bassin plaqué, tiens les poignées sans te tirer dessus.']],
 [/mollets assis/i,['Coussin de cuisses : règle-le pour bloquer le haut du genou (genou à 90°).','Pointes sur le bord de la plateforme, talons dans le vide : étire à fond en bas, monte sur la pointe, pause 1 s.']],
 [/mollets/i,['Épaules sous les coussins, dos droit, pieds largeur de hanches.','Pointes sur le bord de la plateforme, talons dans le vide. Descente lente jusqu\'à l\'étirement complet, pause en haut.','Hammer / Technogym debout : coussins réglés pour que les genoux soient à peine fléchis au départ.']],
 [/squat.*smith|smith.*squat/i,['Barre à hauteur de milieu de poitrine au décrochage. Pieds 20–30 cm devant la barre pour que les genoux ne partent pas trop en avant.','Crochets de sécurité à hauteur de ta taille au point bas.']],
 [/squat/i,['Support de barre à hauteur de milieu de poitrine (tu décroches sans te mettre sur la pointe).','Barre sur les trapèzes, coudes sous la barre. Réglage des sécurités juste sous ton point bas.','Pieds largeur d\'épaules ou un peu plus, pointes légèrement ouvertes.']],
 [/hip thrust|pont fessier/i,['Haut du dos (bas des omoplates) sur le banc, barre dans le pli de hanche avec un coussin.','Pieds largeur d\'épaules, tibias verticaux en haut, menton rentré. Machine : ceinture réglée sur le pli de hanche.']],
 [/soulevé|sdt|good morning|back extension/i,['Barre collée aux jambes, dos plat, hanches en arrière, genoux à peine fléchis.','Back extension : coussin sous le bassin (pas sous le ventre), tu plies aux hanches, pas au dos.']],
 [/pec deck inversé|oiseau machine/i,['Siège : poignées à hauteur d\'épaules (bras parallèles au sol).','Poitrine contre le coussin. Règle l\'écartement de départ : bras devant toi, pas trop en arrière.','Tire avec les coudes, pas avec les mains. Hammer : prise neutre.']],
 [/pec deck|butterfly/i,['Siège : coudes (ou avant-bras) à hauteur des épaules, poignets au niveau du milieu des pecs.','Règle l\'amplitude de départ : bras à peine derrière le plan du corps (étirement sans douleur d\'épaule).','Dos plaqué, épaules basses, pense à rapprocher les coudes, pas les mains.']],
 [/iso-lateral.*(couché|bench)|couché.*hammer/i,['Hammer Iso-Lateral Horizontal Bench Press : tu es allongé sur le dos, fesses et dos plaqués, pieds au sol. Les deux bras poussent indépendamment.','Position de départ : poignées au niveau du milieu de la poitrine, coudes à ~90° et jamais derrière le plan du dos. Si la machine a un réglage de départ, ajuste-le pour que l\'étirement reste confortable pour tes épaules.','Charge les disques de façon égale des deux côtés (la charge est par côté). Utilise la sécurité de départ si présente.','Omoplates serrées, poignets alignés, pousse en arc légèrement convergent, sans verrouiller les coudes. Tu peux aussi travailler un bras à la fois pour corriger un déséquilibre.']],
 [/presse à pec|chest press|convergente|couché machine|couché.*guidé|incliné machine/i,['Siège : les poignées doivent être à hauteur du milieu de la poitrine (au niveau des tétons).','Dos plaqué, omoplates serrées vers l\'arrière, pieds bien posés. Coudes pas plus bas que les épaules au départ (≈ 90°).','Machine Technogym (assise) : règle le siège pour que les poignées partent à mi-poitrine.']],
 [/épaules.*machine|press machine|machine.*épaules/i,['Siège : les poignées partent à hauteur du menton / des épaules, jamais sous les épaules.','Dos plaqué, coudes légèrement devant. Ne verrouille pas les coudes en haut.','Technogym : règle le siège pour que l\'axe de la machine soit au niveau des épaules.']],
 [/tirage vertical|pulldown|tractions assistées/i,['Cale-cuisses : descends-les juste assez pour bloquer les cuisses sans écraser.','Siège : bras tendus en haut sans que les fesses décollent.','Tire la barre vers le haut de la poitrine, buste légèrement penché (10–15°), coudes vers les poches.','Tractions assistées : choisis une assistance qui te permet 8 reps propres.']],
 [/rowing t-bar/i,['Poitrine calée sur le coussin, règle-le à ~10 cm du sternum pour ne pas gêner l\'extension.','Pieds sur la plateforme, dos plat, tire les coudes vers les hanches.']],
 [/poulie basse|horizontal|rowing.*machine|tirage.*machine/i,['Siège : bras tendus, poignées au niveau du milieu de la poitrine / du ventre.','Coussin pectoral à 2 doigts du sternum. Poitrine plaquée, tire les coudes en arrière, serre les omoplates 1 s.','Hammer : prise neutre ou pronation selon la machine, garde les épaules basses.']],
 [/curl pupitre|curl.*machine/i,['Siège : aisselles collées au haut du pupitre, coudes alignés avec l\'axe de rotation de la machine.','Descente complète sans verrouiller les coudes.']],
 [/crunch machine|crunch/i,['Siège : l\'axe de rotation en face du nombril / bas des côtes.','Bas du dos plaqué, enroule le buste avec les abdos (pas avec les bras ni les hanches).']],
 [/dips/i,['Machine assistée : choisis l\'assistance pour 8 reps propres. Poignées à hauteur du bassin.','Lesté : ceinture de dips, buste légèrement penché pour les pecs, droit pour les triceps.']],
 [/katana/i,['Poulie réglée en bas, derrière toi (ou en haut selon la machine), corde ou poignée, dos à la machine, un pas devant pour la stabilité.','Coudes pointés vers l\'avant, bras qui partent derrière la tête : étire la longue portion du triceps, puis étends jusqu\'au bras tendu, sans bouger les coudes.','Conseil : fais-la en premier dans ton biset triceps (muscle frais, étirement maximal), puis termine avec le pushdown.']],
 [/poulie|corde|face pull|pushdown|triceps/i,['Poulie : règle la hauteur selon l\'exo (haute pour triceps, hauteur des yeux pour face pull, basse pour curl).','Coudes fixes le long du corps (triceps) ou hauts (face pull). Pas d\'élan.']],
 [/vélo|assault|bike/i,['Selle : jambe presque tendue au point bas de la pédale (légère flexion ~25–30° du genou).','Guidon à hauteur du bassin ou un peu plus haut. Pas besoin de forcer : cadence 70–90 tours/min, tu peux parler.']],
 [/elliptique|stepper/i,['Reste bien droit, ne t\'accroche pas aux poignées fixes. Résistance modérée, foulée complète.']],
 [/marche en pente|tapis/i,['Pente 8–12 %, vitesse 5–6 km/h, sans te tenir à la barre (ça annule l\'effort).']],
 [/rameur|rowing erg|skierg/i,['Rameur : sangles sur le milieu du pied, amortisseur (damper) à 4–5 : ce n\'est pas la vitesse du ventilateur qui compte.','Ordre : jambes, buste, bras ; au retour, bras, buste, jambes.']],
 [/couché|incliné|développé/i,['Banc : yeux sous la barre au décrochage, omoplates serrées, pieds au sol. Incliné : banc à 30° maximum.','Sécurités (ou aide) réglées à hauteur de poitrine pour les séries lourdes.']],
 [/militaire|arnold|latérales|frontale/i,['Banc à 85–90° pour le militaire assis. Dos plaqué, abdos serrés.','Élévations latérales : coudes légèrement fléchis, monte jusqu\'à hauteur d\'épaules, pas plus.']]
];

