/* Lien photo machine (recherche d'images) */
(function(){const _th=tipHTML;tipHTML=function(name,open){let h=_th(name,open);
 if(/Technogym|Hammer|gym80/.test(name||'')){const q=name.replace(/\(disques\)|\(assistée\)/g,'').replace(/—/g,' ').replace(/\bHammer\b(?! Strength)/,'Hammer Strength').replace(/\s+/g,' ').trim()+' machine';
  h+='<a href="https://www.google.com/search?tbm=isch&q='+encodeURIComponent(q)+'" target="_blank" rel="noopener" style="display:inline-block;margin:6px 0 2px;padding:6px 10px;border-radius:10px;border:1px solid currentColor;font-size:13px;text-decoration:none;opacity:.85">📷 Voir la machine (photos)</a>';}
 return h;};})();
function tipsFor(name){for(const r of TIPS){if(r[0].test(name||''))return r[1];}return null;}
function tipHTML(name,open){const t=tipsFor(name);if(!t)return'';
 return'<details class="tip"'+(open?' open':'')+'><summary>Réglages machine</summary><ul>'+t.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></details>';}
